```c
#include <stdio.h>

/* Leibniz series: pi/4 = 1 - 1/3 + 1/5 - 1/7 + ... */
int main(void)
{
    int n, i, type;
    printf("Input iterations: ");
    if (scanf("%d", &n) != 1 || n <= 0) return 1;
    printf("Input data type (1 float, 2 double, 3 long double): ");
    scanf("%d", &type);

    switch (type) {
    case 1: {                       /* float about 6-7 significant digits */
        float s = 0.0f, t;
        for (i = 0; i < n; i++) {
            t = 1.0f / (2 * i + 1);
            s += (i % 2 == 0) ? t : -t;
        }
        printf("pi(float)=%.6f\n", 4.0f * s);
        break;
    }
    case 2: {                       /* double about 15-16 significant digits */
        double s = 0.0, t;
        for (i = 0; i < n; i++) {
            t = 1.0 / (2 * i + 1);
            s += (i % 2 == 0) ? t : -t;
        }
        printf("pi(double)=%.15f\n", 4.0 * s);
        break;
    }
    case 3: {                       /* long double, highest precision */
        long double s = 0.0L, t;
        for (i = 0; i < n; i++) {
            t = 1.0L / (2 * i + 1);
            s += (i % 2 == 0) ? t : -t;
        }
        printf("pi(long double)=%.18Lf\n", 4.0L * s);
        break;
    }
    default:
        printf("Invalid data type!\n");
    }
    return 0;
}
