int main(void)
{
    long i, n, inside = 0;
    double x, y;
    printf("Input number of samples: ");
    if (scanf("%ld", &n) != 1 || n <= 0) return 1;

    srand((unsigned int)time(NULL));   /* seed with current time */
    for (i = 0; i < n; i++) {
        x = (double)rand() / RAND_MAX; /* uniform point in [0,1] */
        y = (double)rand() / RAND_MAX;
        if (x * x + y * y <= 1.0)      /* inside quarter unit disk */
            inside++;
    }
    printf("pi=%.6f\n", 4.0 * inside / n);
    return 0;
}
